// C++ declarations for qcdloop C-bound functions, translated from mod_qcdloop_c.f.
// These are direct C bindings to the external qcdloop library.

#ifndef MOD_QCDLOOP_C_HPP
#define MOD_QCDLOOP_C_HPP

#include <complex>

extern "C" {

  void qlcachesize(int csize);

  // Complex logarithm with sign convention
  std::complex<double> cln(std::complex<double> x, double isig);

  // Zero/nonzero predicates
  bool qlzero(double x);
  bool qlnonzero(double x);

  // One-point scalar integrals
  std::complex<double> qli1(double m1, double mu2, int ep);
  std::complex<double> qli1c(std::complex<double> m1, double mu2, int ep);

  // Two-point scalar integrals
  std::complex<double> qli2(double p1, double m1, double m2, double mu2, int ep);
  std::complex<double> qli2c(double p1, std::complex<double> m1,
                              std::complex<double> m2, double mu2, int ep);
  std::complex<double> qli2p(double p1, double m1, double m2, double mu2, int ep);
  std::complex<double> qli2pc(double p1, std::complex<double> m1,
                               std::complex<double> m2, double mu2, int ep);

  // Three-point scalar integrals
  std::complex<double> qli3(double p1, double p2, double p3,
                             double m1, double m2, double m3,
                             double mu2, int ep);
  std::complex<double> qli3c(double p1, double p2, double p3,
                              std::complex<double> m1, std::complex<double> m2,
                              std::complex<double> m3, double mu2, int ep);

  // Four-point scalar integrals
  std::complex<double> qli4(double p1, double p2, double p3, double p4,
                             double s12, double s23,
                             double m1, double m2, double m3, double m4,
                             double mu2, int ep);
  std::complex<double> qli4c(double p1, double p2, double p3, double p4,
                              double s12, double s23,
                              std::complex<double> m1, std::complex<double> m2,
                              std::complex<double> m3, std::complex<double> m4,
                              double mu2, int ep);

  // Quad-precision variants.
  // The original Fortran module notes these are broken outside gfortran (no
  // standard c_float128 binding). Guard with __GNUC__ as in the qcdloop library.
#ifdef __GNUC__
  __complex128 qli1q(__float128 m1, __float128 mu2, int ep);
  __complex128 qli2q(__float128 p1, __float128 m1, __float128 m2,
                     __float128 mu2, int ep);
  __complex128 qli3q(__float128 p1, __float128 p2, __float128 p3,
                     __float128 m1, __float128 m2, __float128 m3,
                     __float128 mu2, int ep);
  __complex128 qli4q(__float128 p1, __float128 p2, __float128 p3, __float128 p4,
                     __float128 s12, __float128 s23,
                     __float128 m1, __float128 m2, __float128 m3, __float128 m4,
                     __float128 mu2, int ep);
  __complex128 qli1qc(__complex128 m1, __float128 mu2, int ep);
  __complex128 qli2qc(__float128 p1, __complex128 m1, __complex128 m2,
                      __float128 mu2, int ep);
  __complex128 qli3qc(__float128 p1, __float128 p2, __float128 p3,
                      __complex128 m1, __complex128 m2, __complex128 m3,
                      __float128 mu2, int ep);
  __complex128 qli4qc(__float128 p1, __float128 p2, __float128 p3, __float128 p4,
                      __float128 s12, __float128 s23,
                      __complex128 m1, __complex128 m2, __complex128 m3,
                      __complex128 m4, __float128 mu2, int ep);
#endif // __GNUC__

} // extern "C"

#endif // MOD_QCDLOOP_C_HPP

